#include <bits/stdc++.h>
using namespace std;
// by[x] = uid holding x (0 = free); below[x] = number of locked nodes strictly under x.
// lock/unlock walk only the ancestors: O(log_m n). upgrade visits only subtrees that contain locks.
int n, m, q; vector<long long> by; vector<int> below;
int parent(int x){ return x == 0 ? -1 : (x - 1) / m; }
bool ancestorLocked(int x){ for(x = parent(x); x != -1; x = parent(x)) if(by[x]) return true; return false; }
void bump(int x, int d){ for(x = parent(x); x != -1; x = parent(x)) below[x] += d; }
int main(){ ios::sync_with_stdio(false); cin.tie(nullptr);
  cin >> n >> m >> q; unordered_map<string,int> id; for(int i = 0; i < n; i++){ string s; cin >> s; id[s] = i; }
  by.assign(n, 0); below.assign(n, 0);
  while(q--){ int op; string s; long long uid; cin >> op >> s >> uid; int x = id[s]; bool ok = false;
    if(op == 1){ ok = !by[x] && below[x] == 0 && !ancestorLocked(x); if(ok){ by[x] = uid; bump(x, 1); } }
    else if(op == 2){ ok = by[x] == uid; if(ok){ by[x] = 0; bump(x, -1); } }
    else {
      ok = !by[x] && below[x] > 0 && !ancestorLocked(x); vector<int> found, st{x};
      while(ok && !st.empty()){ int y = st.back(); st.pop_back();
        for(long long c = 1LL*m*y + 1; c <= min<long long>(1LL*m*y + m, n - 1); c++){
          if(by[c]){ if(by[c] != uid){ ok = false; break; } found.push_back(c); }
          if(below[c]) st.push_back(c); } }
      if(ok){ for(int c : found){ by[c] = 0; bump(c, -1); } by[x] = uid; bump(x, 1); } }
    cout << (ok ? "true" : "false") << "\n"; } }

